//     After steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps - 1 <= |generatedPrefix| + steps. ✓
//
//   (final cleanup, steps_f, remaining = maxSteps - steps_f):
//     Same CloseSpanWithinBudget argument as budget-guard. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
